210	    const navLinks = document.querySelectorAll('[data-nav-link]');
211	    const sections = [...navLinks]
212	      .map(link => document.querySelector(link.getAttribute('href')))
213	      .filter(Boolean);
214	
215	    const setActive = (id) => {
216	      navLinks.forEach(link => {
217	        if (link.getAttribute('href') === `#${id}`) {
218	          link.setAttribute('aria-current', 'page');
219	        } else {
220	          link.removeAttribute('aria-current');
221	        }
222	      });
223	    };
224	
