226	
227	    if ('IntersectionObserver' in window) {
228	      const observer = new IntersectionObserver((entries) => {
229	        const visible = entries
230	          .filter(entry => entry.isIntersecting)
231	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
232	        if (visible) setActive(visible.target.id);
233	      }, { rootMargin: '-40% 0px -50% 0px' });
234	      sections.forEach(section => section && observer.observe(section));
235	    }
